package org.example.post;

import java.time.LocalDateTime;
import java.util.List;

// 게시글 상세 조회 응답 — 작성 응답(PostResponse)과 달리 조회수·좋아요·댓글 수를 포함한다
public record PostDetailResponse(
        Long id,
        String boardSlug,
        String title,
        String content,
        List<String> tags,
        String visibility,
        AuthorResponse author,
        Integer viewCount,
        Integer likeCount,
        Integer commentCount,
        String status,
        LocalDateTime publishedAt,
        LocalDateTime createdAt
) {
}

package org.example.post;

// 11-1 발행은 임시저장(DRAFT) 글에만 — 이미 발행됐거나 숨김 글이면 전역 핸들러가 409로 바꾼다
public class PostNotDraftException extends RuntimeException {

    public PostNotDraftException() {
        super("임시저장 글만 발행할 수 있습니다.");
    }
}

